$results = [];
foreach ($queries as $sql) {
    try {
        $pdo->exec($sql);
        $results[] = ["query" => substr(trim($sql), 0, 50) . "...", "status" => "OK"];
    } catch (PDOException $e) {
        $results[] = ["query" => substr(trim($sql), 0, 50) . "...", "status" => "WARN: " . $e->getMessage()];
    }
}

// 4. Verify Tables
